const modData = { ext: 'js', name: 'updateBotDB', platform: 'methods', type: 'mongodb' };
const bot = require( process.cwd() );
const { buildPath } = bot;

/**
 * Builds an updated BotConfig document from the current BotConfig and a default version with the correct `_id` generated by `buildDefaultDB.js`.
 *
 *
 *
 *
 *
 * @returns { Object<string, *> } The completed modified BotConfig document, or a diagnostic document if building fails.
 */
module.exports = ( curr, result, botIDs ) => {
  try {
    const oldConfig = JSON.parse( curr.Backup.Config.CachedString );
    const newConfig = JSON.parse( result.Backup.Config.CachedString );
//    Languages should always be updated.
    if ( newConfig.Name === oldConfig.Name ) { result.Name = curr.Name; }
    // if ( newConfig.Contacts !== oldConfig.Contacts ) { result.Contacts = curr.Contacts; }
    // if ( curr.Personas !== result.Personas ) { result.Personas = curr.Personas; }
    // if ( curr.Platforms !== result.Platforms ) { result.Platforms = curr.Platforms; }
    // if ( curr.WebDash !== result.WebDash ) { result.WebDash = curr.WebDash; }
    if ( newConfig.Verbosity === oldConfig.Verbosity ) { result.Verbosity = curr.Verbosity; }
//    Version should always be updated.
  }
  catch ( updaterError ) {
    console.error( 'Failed to %s: %o', buildPath( modData ).path, updaterError );
    const errID = 'Error-' + ( botIDs.filter( id => id.startsWith( 'Error' ) ) ).length + 1;
    return {
      _id: errID,
      Backup: {
        Config: {
          CachedString: JSON.stringify( {
            stack: updaterError.stack,
            string: updaterError.toString(),
          } ),
          LastModifiedAt: new Date(),
        },
      },
      Name: 'Failed Default Database Build',
      Verbosity: 5,
      Version: new Date(),
    };
  }
}
